<template><view class="tabbar glass"><view v-for="item in items" :key="item.path" class="tab" :class="{active: current === item.path}" @click="go(item.path)"><text class="icon">{{item.icon}}</text><text>{{item.label}}</text></view></view></template><script setup lang="ts">import { computed } from 'vue'; import { useRoute } from 'vue-router'; const route=useRoute(); const current=computed(()=>route.path); const items=[{path:'/pages/index/index',label:'首页',icon:'⌂'},{path:'/pages/ai/index',label:'AI顾问',icon:'✦'},{path:'/pages/policy/index',label:'保单',icon:'▤'},{path:'/pages/mine/index',label:'我的',icon:'○'}]; const go=(path:string)=>uni.switchTab({url:path})</script><style scoped lang="scss">.tabbar{position:fixed;left:28rpx;right:28rpx;bottom:30rpx;height:112rpx;z-index:10;display:flex;align-items:center;justify-content:space-around}.tab{display:flex;flex-direction:column;align-items:center;gap:4rpx;color:#8b8eaf;font-size:21rpx;min-width:110rpx}.icon{font-size:38rpx;line-height:1}.active{color:#5049bc;font-weight:700}.active .icon{transform:translateY(-4rpx)}</style>
